import React from 'react';
import { useParams, useNavigate, Navigate } from 'react-router-dom';
import { makeStyles } from '@mui/styles';
import Box from '@mui/material/Box';
import Card from '@mui/material/Card';
import CardContent from '@mui/material/CardContent';
import CardHeader from '@mui/material/CardHeader';
import Chip from '@mui/material/Chip';
import Divider from '@mui/material/Divider';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Typography from '@mui/material/Typography';
import Avatar from '@mui/material/Avatar';
import TableChartIcon from '@mui/icons-material/TableChart';
import SEO from '../components/SEO';
import Breadcrumb from '../components/Breadcrumb';
import Sidebar from '../components/Sidebar';
import ShareButtons from '../components/ShareButtons';
import YouTubeLink from '../components/YouTubeLink';
import Footer from '../components/Footer';
import { allSeasons } from '../utils/generals';
import { alpha } from '@mui/material/styles';
import { withStyles } from '@mui/styles';

const SLUG_MAP = {
  'serie-A':   'A',
  'serie-B':   'B',
  'serie-C1':  'C1',
  'serie-1RS': '1RS',
};

const LEAGUE_INFO = {
  'A':   { name: 'Serie A',           shortName: 'Serie A',      color: '#082D68', chipBg: '#e8edf5' },
  'B':   { name: 'Serie B',           shortName: 'Serie B',      color: '#CA2331', chipBg: '#faeaeb' },
  'C1':  { name: 'Serie C1',          shortName: 'Serie C1',     color: '#E87722', chipBg: '#fef3ea' },
  '1RS': { name: 'Prima Divisione',   shortName: 'Prima Div.',   color: '#6A0DAD', chipBg: '#f3eaf8' },
};

const StyledRow = withStyles((theme) => ({
  root: {
    cursor: 'pointer',
    '&:nth-of-type(odd)': { backgroundColor: theme.palette.action.hover },
    '&:hover': { backgroundColor: alpha(theme.palette.primary.main, 0.08) },
  },
}))(TableRow);

const useStyles = makeStyles((theme) => ({
  navCard: {
    borderTop: '4px solid #CA2331',
    marginBottom: theme.spacing(2),
    overflow: 'hidden',
  },
  navHeader: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1.5),
    padding: theme.spacing(1, 2),
    backgroundImage: 'url(https://www.archiviorossoblu.it/images/header-gradient-bg.jpg)',
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    position: 'relative',
    '&::before': {
      content: '""',
      position: 'absolute',
      inset: 0,
      background: 'rgba(8,45,104,0.60)',
    },
    '& > *': { position: 'relative', zIndex: 1 },
  },
  brand: {
    fontWeight: 800,
    fontSize: '1.6rem',
    color: '#F0C040',
    textDecoration: 'none',
    flex: 1,
  },
  statsRow: {
    display: 'flex',
    gap: theme.spacing(1.5),
    flexWrap: 'wrap',
    marginBottom: theme.spacing(2),
  },
  statBox: {
    flex: '1 1 120px',
    borderRadius: 10,
    padding: theme.spacing(1.5, 2),
    background: '#fff',
    boxShadow: '0 2px 8px rgba(0,0,0,0.07)',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    gap: 4,
  },
  statValue: {
    fontWeight: 800,
    fontSize: '1.8rem',
    lineHeight: 1,
  },
  statLabel: {
    fontSize: '0.72rem',
    fontWeight: 600,
    letterSpacing: '0.06em',
    textTransform: 'uppercase',
    color: 'rgba(0,0,0,0.45)',
    textAlign: 'center',
  },
  header: {
    fontWeight: 700,
    fontSize: '0.78rem',
    padding: '8px 8px',
  },
  yearLink: {
    textDecoration: 'underline',
    fontWeight: 600,
    fontSize: '0.85rem',
    color: '#082D68',
    '&:hover': { color: '#CA2331' },
  },
  avatar: {
    width: 32,
    height: 32,
    fontSize: '0.7rem',
    fontWeight: 700,
  },
}));

export default function LeaguePage() {
  const classes = useStyles();
  const { league: slug } = useParams();
  const navigate = useNavigate();

  const leagueCode = SLUG_MAP[slug];
  const info = LEAGUE_INFO[leagueCode];
  if (!info) return <Navigate to="/cagliari-calcio/stagioni" replace />;

  const seasons = allSeasons
    .filter(s => s.league === leagueCode)
    .sort((a, b) => b.year.localeCompare(a.year));

  const withPos   = seasons.filter(s => Number(s.position) > 0);
  const bestPos   = withPos.length > 0 ? Math.min(...withPos.map(s => Number(s.position))) : null;
  const totalWins = seasons.reduce((acc, s) => acc + Math.max(0, Number(s.v)), 0);
  const totalGF   = seasons.reduce((acc, s) => acc + Math.max(0, Number(s.gf)), 0);

  const handleSeasonSelect = (id, year) => {
    localStorage.setItem('arb_seasonID', String(id));
    localStorage.setItem('arb_seasonLabel', year);
    navigate('/cagliari-calcio/stagioni');
  };

  return (
    <div>
      <SEO
        title={info.name}
        description={`Tutte le stagioni del Cagliari Calcio in ${info.name}: classifiche, risultati e statistiche.`}
        path={`/cagliari-calcio/stagioni/${slug}`}
      />

      <Card className={classes.navCard}>
        <div className={classes.navHeader}>
          <Sidebar iconColor="#F0C040" />
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, flex: 1 }}>
            <img
              src="https://www.archiviorossoblu.it/images/sun-gold-sella-bg.png"
              alt="logo"
              title="ArchivioRossoBlu"
              style={{ width: 80, height: 80, flexShrink: 0 }}
            />
            <Typography component="a" href="/cagliari-calcio" className={classes.brand} style={{ flex: 'none' }}>
              <span className="brand-short" title="ArchivioRossoBlu">ARB</span>
              <span className="brand-full">ArchivioRossoBlu</span>
            </Typography>
          </div>
          <YouTubeLink />
          <ShareButtons />
          <Chip
            label={info.shortName}
            size="small"
            style={{ fontWeight: 700, backgroundColor: info.color, color: '#fff' }}
          />
        </div>
        <Divider />
      </Card>

      <Box p={2}>
        <Breadcrumb items={[{ label: 'Home', href: '/cagliari-calcio' }, { label: 'Stagioni', href: '/cagliari-calcio/stagioni' }, { label: info.name }]} />
        {/* Stats summary */}
        <div className={classes.statsRow}>
          <div className={classes.statBox}>
            <Typography className={classes.statLabel}>Stagioni</Typography>
            <Typography className={classes.statValue} style={{ color: info.color }}>
              {seasons.length}
            </Typography>
          </div>
          {bestPos && (
            <div className={classes.statBox}>
              <Typography className={classes.statLabel}>Miglior posizione</Typography>
              <Typography className={classes.statValue} style={{ color: info.color }}>
                {bestPos}°
              </Typography>
            </div>
          )}
          <div className={classes.statBox}>
            <Typography className={classes.statLabel}>Vittorie totali</Typography>
            <Typography className={classes.statValue} style={{ color: info.color }}>
              {totalWins}
            </Typography>
          </div>
          <div className={classes.statBox}>
            <Typography className={classes.statLabel}>Gol segnati</Typography>
            <Typography className={classes.statValue} style={{ color: info.color }}>
              {totalGF}
            </Typography>
          </div>
          <div className={classes.statBox} style={{ gap: 5, order: -1 }}>
            <Typography className={classes.statLabel} style={{ marginBottom: 2 }}>Serie</Typography>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, justifyContent: 'center' }}>
              {Object.entries(SLUG_MAP).map(([s, code]) => {
                const active = s === slug;
                const li = LEAGUE_INFO[code];
                const label = { A: 'A', B: 'B', C1: 'C1', '1RS': 'Prima Div.' }[code];
                return (
                  <Chip
                    key={s}
                    label={label}
                    size="small"
                    onClick={() => !active && navigate(`/cagliari-calcio/stagioni/${s}`)}
                    style={{
                      fontWeight: 700,
                      fontSize: '0.7rem',
                      height: 22,
                      cursor: active ? 'default' : 'pointer',
                      backgroundColor: active ? li.color : 'transparent',
                      color: active ? '#fff' : li.color,
                      border: `2px solid ${li.color}`,
                    }}
                  />
                );
              })}
            </div>
          </div>
        </div>

        {/* Seasons table */}
        <Card style={{ borderTop: `4px solid ${info.color}` }}>
          <CardHeader
            avatar={<TableChartIcon style={{ color: info.color, fontSize: '1.8rem' }} />}
            title={`Cagliari in ${info.name}`}
            subheader={`${seasons.length} stagioni — clicca una riga per aprire la stagione`}
          />
          <Divider />
          <CardContent style={{ padding: 0 }}>
            <TableContainer>
              <Table size="small" aria-label={`stagioni ${info.name}`}>
                <TableHead>
                  <TableRow>
                    <TableCell className={classes.header}>Anno</TableCell>
                    <TableCell className={classes.header}>Pos.</TableCell>
                    <TableCell className={classes.header}>Punti</TableCell>
                    <TableCell className={classes.header}>V</TableCell>
                    <TableCell className={classes.header}>P</TableCell>
                    <TableCell className={classes.header}>S</TableCell>
                    <TableCell className={classes.header}>GF</TableCell>
                    <TableCell className={classes.header}>GS</TableCell>
                    <TableCell className={classes.header}>DR</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {seasons.map((row) => (
                    <StyledRow key={row.id} onClick={() => handleSeasonSelect(row.id, row.year)}>
                      <TableCell>
                        <Typography className={classes.yearLink}>{row.year}</Typography>
                      </TableCell>
                      <TableCell>
                        <Typography variant="body2" color="textSecondary">
                          {Number(row.position) > 0 ? `${row.position}°` : '—'}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Avatar
                          className={classes.avatar}
                          style={{ backgroundColor: info.color, color: '#fff' }}
                        >
                          {row.points}
                        </Avatar>
                      </TableCell>
                      <TableCell><Typography variant="body2" color="textSecondary">{row.v}</Typography></TableCell>
                      <TableCell><Typography variant="body2" color="textSecondary">{row.d}</Typography></TableCell>
                      <TableCell><Typography variant="body2" color="textSecondary">{row.l}</Typography></TableCell>
                      <TableCell><Typography variant="body2" color="textSecondary">{row.gf}</Typography></TableCell>
                      <TableCell><Typography variant="body2" color="textSecondary">{row.gs}</Typography></TableCell>
                      <TableCell>
                        <Typography
                          variant="body2"
                          style={{ color: Number(row.dr) >= 0 ? '#2e7d32' : '#c62828', fontWeight: 600 }}
                        >
                          {Number(row.dr) > 0 ? `+${row.dr}` : row.dr}
                        </Typography>
                      </TableCell>
                    </StyledRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </CardContent>
        </Card>
      </Box>

      <Footer />
    </div>
  );
}
